const { PDFDocument, rgb } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const font = await doc.embedFont(fs.readFileSync('/usr/share/fonts/workspacex/NotoSansSC-Common.otf'));

  const pageW = 595, pageH = 842;
  const ml = 50, mr = 50, mt = 780;
  const lineH = 18;
  let y = mt;

  function title(text) {
    page.drawText(text, { x: ml, y, size: 26, font, color: rgb(0.13, 0.30, 0.55) });
    y -= 36;
  }
  function heading(text) {
    y -= 6;
    page.drawText(text, { x: ml, y, size: 16, font, color: rgb(0.20, 0.40, 0.65) });
    y -= 22;
  }
  function body(text) {
    page.drawText(text, { x: ml + 10, y, size: 11, font });
    y -= lineH;
  }
  function bullet(text) {
    page.drawText('• ' + text, { x: ml + 10, y, size: 11, font });
    y -= lineH;
  }
  function sep() {
    y -= 4;
    page.drawLine({ start: { x: ml, y }, end: { x: pageW - mr, y }, thickness: 0.5, color: rgb(0.7, 0.7, 0.7) });
    y -= 14;
  }

  // === Page 1 ===
  let page = doc.addPage([pageW, pageH]);

  title('我能为你做什么');
  body('以下是我当前具备的核心能力概览，涵盖文档、数据、研究、沟通与自动化。');
  y -= 8;

  heading('一、文档与文件处理');
  bullet('创建 PDF、Word、Excel、PowerPoint 文件（支持中文排版）');
  bullet('读取并理解上传的 PDF / Office / CSV 原件内容');
  bullet('从会议转录生成结构化会议纪要（决策 + 行动项）');
  bullet('将访谈记录综合为主题分析报告，保留可定位引文');
  sep();

  heading('二、数据分析与可视化');
  bullet('分析 CSV / XLSX / JSON 数据，输出可复现的计算与结论');
  bullet('生成静态图表（柱状图、折线图、饼图等），校验标签与单位');
  bullet('数据质量说明与缺失值标注');
  sep();

  heading('三、研究与知识问答');
  bullet('联网搜索公开信息，形成带引用的研究报告');
  bullet('基于组织内部资料回答政策 / 项目知识问题（附出处）');
  bullet('用户研究规划：制定研究计划、招募条件与中立访谈提纲');
  sep();

  heading('四、沟通与写作');
  bullet('撰写内部公告、领导更新、FAQ、3P 周报等沟通草稿');
  bullet('准备会议背景材料、议程与预读文档');
  bullet('生成项目状态报告（周报 / 里程碑 / 领导简报）');
  sep();

  heading('五、视觉与交互产物');
  bullet('设计海报、配图的构图与文案，生成图片或精确排版');
  bullet('创建自包含交互式网页产物（响应式布局、状态管理）');
  bullet('绘制 / 编辑 Mermaid 流程图与画布 Markdown');
  bullet('生成 MAAU Canvas（最小智能体可执行单元画布）');
  sep();

  heading('六、音频与转写');
  bullet('将音频文件转录为可审阅文本，保留时间范围标记');
  sep();

  heading('七、技能与自动化');
  bullet('将重复工作流整理为可复用的技能草稿包');
  bullet('在沙箱中执行 Shell 命令、脚本与数据处理任务');

  // Footer
  y -= 20;
  page.drawText('由 WorkspaceX Agent 自动生成', { x: ml, y, size: 9, font, color: rgb(0.5, 0.5, 0.5) });

  const bytes = await doc.save();
  fs.writeFileSync('/workspace/my-capabilities.pdf', bytes);
  console.log('PDF generated successfully.');
})().catch(e => { console.error(e.stack); process.exit(1); });
